TWComponent.script:
tw.local.filteredTeam = new tw.object.Team();
tw.local.filteredTeam.members = new tw.object.listOf.String();
tw.local.filteredTeam.managerTeam = tw.local.originalTeam.managerTeam;
tw.local.filteredTeam.name = tw.local.originalTeam.name;

log.info("filtered team before branch call# "+tw.local.filteredTeam.name);

var branch_users = tw.system.org.findRoleByName(tw.local.branchCode).allUsers;
var group_users = tw.system.org.findRoleByName(tw.local.branchGroupName).allUsers;
	
log.info("users::: "+ branch_users);
	for (var i=0;i<branch_users.listLength;i++)
	{
		for(var j=0;j<group_users.listLength;j++)
		{
			if(branch_users[i].name == group_users[j].name && group_users[j].name != "") 
			{
				tw.local.filteredTeam.members[j] = group_users[j].name;
			}
		}
		
	}
	log.info("Filtered team :# "+tw.local.filteredTeam);

tw.local.TEAM_NAME = tw.local.branchGroupName;
tw.local.FILTER_BRANCH = tw.local.branchCode;

if(tw.local.branchGroupName == ""+tw.epv.TeamsNameBPM.Compliance_MKR){
	tw.local.TEAM_MANAGER = "" + tw.epv.TeamsNameBPM.Compliance_Maker_Manager;
	tw.local.PARENT_TEAM_NAME = "" + tw.epv.BPMTeamsNamesReassign.Compliance_Maker_team;
}
else{

	tw.local.TEAM_MANAGER = "" + tw.epv.TeamsNameBPM.BranchMakerManager;
	tw.local.PARENT_TEAM_NAME = "" + tw.epv.BPMTeamsNamesReassign.Branch_Opereration_Maker;
}
//tw.local.TEAM_MANAGER
//tw.local.PARENT_TEAM_NAME

tw.local.filteredTeam = new tw.object.Team();
tw.local.filteredTeam.members = new tw.object.listOf.String();
tw.local.filteredTeam.managerTeam = tw.local.originalTeam.managerTeam;
tw.local.filteredTeam.name = tw.local.originalTeam.name;

log.info("<<<<<HUB User>>>>>")
log.info(tw.local.user)

if(!!tw.local.user ){
      tw.local.hubGroupName = tw.local.hubGroupName+"_EXE_MKR";
//  var isCRMaker = tw.system.org.findUserByName(tw.local.user).isInRole(tw.local.hubGroupName+"_CR_MKR");
//
//  if(isCRMaker){
//      tw.local.hubGroupName = tw.local.hubGroupName+"_CR_MKR";
//
//      
//      }
//  else{
//
//      }

} 

var users = tw.system.org.findRoleByName(tw.local.hubGroupName).allUsers;
	
log.info("users::: "+ users);
	for (var i = 0; i < users.listLength ; i++)
	{
		tw.local.filteredTeam.members[i] = users[i].name;
	}
	
if(tw.local.hubGroupName.split('_')[4] == "COMP"){
	tw.local.TEAM_MANAGER = "" + tw.epv.TeamsNameBPM.HUB_COMP_CHKR_Manager;
	tw.local.PARENT_TEAM_NAME = "" + tw.epv.BPMTeamsNamesReassign.Hub_Compliance_Checker;
	//tw.local.TEAM_NAME = "" + tw.epv.TeamsNameBPM.HUB_COMP_CHKR;
}
else {
	
	      tw.local.PARENT_TEAM_NAME = "" + tw.epv.BPMTeamsNamesReassign.idc_hub_exe_Maker;
      	tw.local.TEAM_MANAGER = "" + tw.epv.TeamsNameBPM.HUB_EXE_Manager;
//	  if(isCRMaker){
//  	     tw.local.PARENT_TEAM_NAME = "" + tw.epv.BPMTeamsNamesReassign.idc_hub_cr;
//   	     tw.local.TEAM_MANAGER = "" + tw.epv.TeamsNameBPM.HUB_CR_MKR_Manager;
//   	   //  tw.local.TEAM_NAME = "" + tw.epv.TeamsNameBPM.HUB_CR_MKR;
//      
//      }
// 	 else{
//      	//tw.local.TEAM_NAME = "" + tw.epv.TeamsNameBPM.HUB_EXE_MKR;
//      }
      
      
}


tw.local.TEAM_NAME = tw.local.hubGroupName;
tw.local.FILTER_BRANCH = tw.local.hubCode;

